#include <dyf.h>
#include <cstdio>
#include <exception>

int main()
{
    try
    {
        constexpr uint32_t width = 640, height = 480;
        dyf::Platform::Window window(width, height, "dy_engine / Canvas");
        if (!window.GetHandle()) return 1;

        // 창은 렌더러보다 오래 살아 있어야 한다.
        auto renderer = dyf::Renderer::Create(window.GetHandle());
        if (!renderer) return 1;

        dyf::Canvas canvas(width, height);
        if (!canvas.IsValid()) return 1;
        canvas.Clear({0.04f, 0.06f, 0.10f, 1.0f});
        canvas.FillRect({80, 100, 220, 140}, {0.10f, 0.65f, 0.95f, 1.0f});
        canvas.FillCircle({430, 230}, 70.0f, {1.0f, 0.65f, 0.15f, 1.0f});
        canvas.Line({80, 340}, {540, 340}, {1, 1, 1, 1}, 3.0f);

        while (window.IsRunning())
        {
            window.PollEvents();
            if (!window.IsRunning()) break;
            // 같은 CPU 명령 목록을 여러 프레임에서 다시 그릴 수 있다.
            if (!renderer->Render(canvas)) return 1;
        }
        return 0;
    }
    catch (const std::exception& error)
    {
        std::fprintf(stderr, "%s\n", error.what());
        return 1;
    }
}

#include <dyf/Platform/Window.h>
#include <dyf/RHI.h>
#include <chrono>
#include <cstdio>
#include <exception>
#include <memory>
#include <thread>

int main()
{
    try
    {
        constexpr uint32_t width = 640, height = 480;
        dyf::Platform::Window window(width, height, "dy_engine / RHI clear");
        if (!window.GetHandle()) return 1;

        // IDevice::Create는 소유권이 있는 포인터를 반환한다.
        std::unique_ptr<dyf::RHI::IDevice> device(
            dyf::RHI::IDevice::Create(dyf::RHI::DeviceDesc{}));
        if (!device) return 1;

        dyf::RHI::SwapchainDesc swapchain;
        swapchain.window = window.GetHandle();
        swapchain.format = dyf::RHI::Format::B8G8R8A8_UNORM;
        // 네이티브 창은 0으로 크기를 유도하고, Null 검증은 명시 크기를 요구한다.
        if (!device->Supports(dyf::RHI::Feature::Rasterization))
        {
            swapchain.initialWidth = width;
            swapchain.initialHeight = height;
        }
        if (!device->CreateSwapchain(swapchain)) return 1;

        while (window.IsRunning())
        {
            window.PollEvents();
            if (!window.IsRunning()) break;
            if (!device->BeginFrame())
            {
                if (device->IsLost()) return 1;
                std::this_thread::sleep_for(std::chrono::milliseconds(16));
                continue;
            }

            // ResourceScope는 device보다 먼저 파괴된다.
            dyf::RHI::ResourceScope frameResources(*device);
            auto* commands = frameResources.Keep(device->AcquireCommandList());
            auto* backBuffer = device->GetBackBuffer();
            if (!backBuffer) return 1; // 스왑체인 소유이므로 Keep/DestroyTexture 금지.

            const dyf::RHI::ResourceBarrierDesc begin{
                nullptr, backBuffer, dyf::RHI::ResourceState::Present,
                dyf::RHI::ResourceState::RenderTarget, {}};
            commands->ResourceBarrier(&begin, 1);

            dyf::RHI::ColorAttachment color;
            color.texture = backBuffer;
            color.loadOp = dyf::RHI::LoadOp::Clear;
            color.storeOp = dyf::RHI::StoreOp::Store;
            color.clearColor[0] = 0.04f;
            color.clearColor[1] = 0.06f;
            color.clearColor[2] = 0.10f;
            color.clearColor[3] = 1.0f;
            commands->BeginRendering({&color, 1, nullptr});
            commands->EndRendering();

            const dyf::RHI::ResourceBarrierDesc end{
                nullptr, backBuffer, dyf::RHI::ResourceState::RenderTarget,
                dyf::RHI::ResourceState::Present, {}};
            commands->ResourceBarrier(&end, 1);

            // 기록 실패는 Close, 제출 실패는 Submit에서 확인한다.
            if (!commands->Close()) return 1;
            if (!device->Submit(&commands, 1)) return 1;
            if (!device->Present()) return 1;
        }
        return device->WaitIdle() ? 0 : 1;
    }
    catch (const std::exception& error)
    {
        // ResourceScope::Keep(nullptr)도 예외로 보고된다.
        std::fprintf(stderr, "%s\n", error.what());
        return 1;
    }
}

#include <dyf.h>
#include <dyf/Extends/Model.h>
#include <string>

bool AddAnimatedModel(dyf::ModelScene& scene, const std::string& path,
                      dyf::ModelInstanceID& instance)
{
    dyf::ModelSceneDesc desc;
    desc.path = path;
    instance = dyf::ModelInstanceID::Invalid;
    if (!dyf::AddModelToScene(scene, desc, &instance)) return false;

    const auto* model = scene.TryGetModelInstance(instance);
    if (!model) return false;
    if (!model->clips.empty() && !scene.PlayAnimation(instance, 0)) return false;
    return true;
}

#include <dyf.h>
#include <dyf/Extends/Model.h>
#include <chrono>

bool RunModelLoop(dyf::Platform::Window& window, dyf::Renderer& renderer,
                  dyf::ModelScene& scene, const dyf::Camera& camera)
{
    dyf::ModelRenderer modelRenderer(renderer);
    auto previous = std::chrono::steady_clock::now();
    while (window.IsRunning())
    {
        window.PollEvents();
        if (!window.IsRunning()) break;
        const auto now = std::chrono::steady_clock::now();
        const float deltaSeconds = std::chrono::duration<float>(now - previous).count();
        previous = now;
        if (!scene.UpdateAnimations(deltaSeconds)) return false;
        if (!modelRenderer.Render(scene, camera)) return false;
    }
    return true;
}

cbuffer DrawConstants : register(b10, space0)
{
    column_major float4x4 viewProjectionMatrix;
    column_major float4x4 modelMatrix;
    uint textureFlags;
    uint padding0;
    uint padding1;
    uint padding2;
    float4 emissiveColor;
    float4 baseColor;
    float4 materialParams;
};
struct Input
{
    float3 position : TEXCOORD0;
    float3 normal : TEXCOORD1;
    float2 uv : TEXCOORD2;
    float4 tangent : TEXCOORD3;
};
struct Output
{
    float4 position : SV_POSITION;
    float4 color : TEXCOORD0;
};
Output main(Input input)
{
    Output output;
    output.position = mul(viewProjectionMatrix,
        mul(modelMatrix, float4(input.position, 1.0)));
    output.color = baseColor;
    return output;
}

float4 main(float4 position : SV_POSITION, float4 color : TEXCOORD0) : SV_TARGET
{
    return color;
}

#version 450
layout(location = 0) in vec3 inPosition;
layout(location = 1) in vec3 inNormal;
layout(location = 2) in vec2 inUv;
layout(location = 3) in vec4 inTangent;
layout(push_constant) uniform DrawConstants
{
    mat4 viewProjectionMatrix;
    mat4 modelMatrix;
    uint textureFlags;
    uint padding0;
    uint padding1;
    uint padding2;
    vec4 emissiveColor;
    vec4 baseColor;
    vec4 materialParams;
